function bk_core_get($key){$settings=wp_parse_args(get_option('bk_core_settings',array()),bk_core_defaults());return isset($settings[$key])?$settings[$key]:'';}

/* Dedicated admin slug prevents the Baran Khanomy menu from colliding with documentation/PDF links. */
add_action('admin_menu',function(){add_menu_page('تنظیمات قالب باران خانومی','باران خانومی','manage_options','baran-khanomy-theme-settings','bk_core_settings_page','dashicons-admin-customizer',58);},99);
add_action('admin_enqueue_scripts',function($hook){if('toplevel_page_baran-khanomy-theme-settings'!==$hook)return;wp_enqueue_media();wp_enqueue_script('jquery');});
add_action('admin_init',function(){register_setting('bk_core_settings_group','bk_core_settings',array('sanitize_callback'=>function($input){$defaults=bk_core_defaults();$output=array();$numeric_keys=array('font_hero_title','font_benefit_title','font_benefit_text','font_categories_title','font_courses_title','font_course_title','font_about_title','font_works_title','font_testimonials_title','font_footer_title','font_footer_text','font_signature');foreach($defaults as $key=>$default){$value=isset($input[$key])?$input[$key]:$default;if(in_array($key,array('hero_image','about_image','benefit_1_icon','benefit_2_icon','benefit_3_icon'),true)){$output[$key]=esc_url_raw($value);}elseif(in_array($key,$numeric_keys,true)){$number=absint($value);$output[$key]=($number>=8&&$number<=72)?(string)$number:$default;}else{$output[$key]=sanitize_textarea_field($value);}}return $output;}));});
function bk_media_field($key,$label,$value){?><tr><th scope="row"><?php echo esc_html($label);?></th><td><div class="bk-media-field"><input type="hidden" class="bk-media-value" name="bk_core_settings[<?php echo esc_attr($key);?>]" value="<?php echo esc_attr($value);?>"><div class="bk-media-preview" style="margin-bottom:10px;"><?php if($value):?><img src="<?php echo esc_url($value);?>" alt="" style="display:block;max-width:180px;max-height:100px;border-radius:10px;object-fit:contain;"><?php endif;?></div><button type="button" class="button bk-select-media">انتخاب / آپلود</button><button type="button" class="button bk-remove-media" <?php echo $value?'':'style="display:none;"';?>>حذف</button><p class="description">از کتابخانه رسانه وردپرس انتخاب یا آپلود کنید.</p></div></td></tr><?php }
function bk_text_field($settings,$key,$label,$textarea=false){?><tr><th scope="row"><label for="bk-<?php echo esc_attr($key);?>"><?php echo esc_html($label);?></label></th><td><?php if($textarea):?><textarea class="large-text" rows="4" id="bk-<?php echo esc_attr($key);?>" name="bk_core_settings[<?php echo esc_attr($key);?>]"><?php echo esc_textarea($settings[$key]);?></textarea><?php else:?><input class="regular-text" type="text" id="bk-<?php echo esc_attr($key);?>" name="bk_core_settings[<?php echo esc_attr($key);?>]" value="<?php echo esc_attr($settings[$key]);?>"><?php endif;?></td></tr><?php }
function bk_font_field($settings,$key,$label){?><tr><th scope="row"><label for="bk-<?php echo esc_attr($key);?>"><?php echo esc_html($label);?></label></th><td><input class="small-text" type="number" min="8" max="72" step="1" id="bk-<?php echo esc_attr($key);?>" name="bk_core_settings[<?php echo esc_attr($key);?>]" value="<?php echo esc_attr($settings[$key]);?>"> <span>px</span></td></tr><?php }
function bk_core_settings_page(){if(!current_user_can('manage_options'))return;$settings=wp_parse_args(get_option('bk_core_settings',array()),bk_core_defaults());?><div class="wrap" dir="rtl"><h1>تنظیمات قالب باران خانومی</h1><p>دوره‌ها از Tutor LMS مدیریت می‌شوند. محتوای اختصاصی صفحه اصلی از این بخش و نظرات و نمونه‌کارها از منوهای اختصاصی مدیریت می‌شوند.</p><form method="post" action="options.php"><?php settings_fields('bk_core_settings_group');?><h2>هیرو</h2><table class="form-table" role="presentation"><?php bk_media_field('hero_image','تصویر هیرو',$settings['hero_image']);?></table><h2>بخش معرفی</h2><table class="form-table" role="presentation"><?php bk_media_field('about_image','تصویر این بخش',$settings['about_image']);bk_text_field($settings,'about_badge','برچسب');bk_text_field($settings,'about_title','عنوان');bk_text_field($settings,'about_text','توضیحات',true);bk_text_field($settings,'about_primary','دکمه اصلی');bk_text_field($settings,'about_secondary','دکمه دوم');?></table><h2>آمار و مزیت‌ها</h2><table class="form-table" role="presentation"><?php bk_media_field('benefit_1_icon','مزیت اول - آیکن',$settings['benefit_1_icon']);bk_text_field($settings,'benefit_1_title','مزیت اول - عنوان');bk_text_field($settings,'benefit_1_text','مزیت اول - توضیح');bk_media_field('benefit_2_icon','مزیت دوم - آیکن',$settings['benefit_2_icon']);bk_text_field($settings,'benefit_2_title','مزیت دوم - عنوان');bk_text_field($settings,'benefit_2_text','مزیت دوم - توضیح');bk_media_field('benefit_3_icon','مزیت سوم - آیکن',$settings['benefit_3_icon']);bk_text_field($settings,'benefit_3_title','مزیت سوم - عنوان');bk_text_field($settings,'benefit_3_text','مزیت سوم - توضیح');bk_text_field($settings,'stat_courses','عدد آموزش‌ها');bk_text_field($settings,'stat_courses_label','عنوان آموزش‌ها');bk_text_field($settings,'stat_students','عدد هنرجویان');bk_text_field($settings,'stat_students_label','عنوان هنرجویان');bk_text_field($settings,'stat_experience','عدد سابقه');bk_text_field($settings,'stat_experience_label','عنوان سابقه');?></table><h2>عنوان بخش‌ها</h2><table class="form-table" role="presentation"><?php bk_text_field($settings,'categories_kicker','دسته‌بندی - برچسب');bk_text_field($settings,'categories_title','دسته‌بندی - عنوان');bk_text_field($settings,'categories_link','دسته‌بندی - لینک');bk_text_field($settings,'all_courses_label','برچسب همه دوره‌ها');bk_text_field($settings,'courses_kicker','دوره‌ها - برچسب');bk_text_field($settings,'courses_title','دوره‌ها - عنوان');bk_text_field($settings,'course_button_label','دوره‌ها - دکمه');bk_text_field($settings,'all_courses_button','دوره‌ها - دکمه همه');bk_text_field($settings,'no_courses_text','دوره‌ها - حالت خالی');bk_text_field($settings,'works_kicker','نمونه‌کار - برچسب');bk_text_field($settings,'works_title','نمونه‌کار - عنوان');bk_text_field($settings,'works_button','نمونه‌کار - دکمه');bk_text_field($settings,'testimonials_kicker','نظرات - برچسب');bk_text_field($settings,'testimonials_title','نظرات - عنوان');bk_text_field($settings,'no_testimonials_text','نظرات - حالت خالی');?></table><h2>فوتر و اطلاعات تماس</h2><table class="form-table" role="presentation"><?php bk_text_field($settings,'footer_cta','عنوان CTA');bk_text_field($settings,'footer_description','توضیح CTA',true);bk_text_field($settings,'phone','شماره تماس');bk_text_field($settings,'email','ایمیل');bk_text_field($settings,'footer_brand_text','توضیح برند',true);bk_text_field($settings,'copyright','کپی‌رایت');?></table><h2>امضای طراح</h2><table class="form-table" role="presentation"><tr><th scope="row">متن امضا</th><td><code>طراحی شده با ♥ توسط &lt;a href="http://sabkekar.ir" target="_blank" rel="noopener noreferrer"&gt;سبک کار&lt;/a&gt;</code><p class="description">این امضا در انتهای فوتر سایت نمایش داده می‌شود.</p></td></tr></table><h2>اندازه فونت بخش‌ها</h2><p>اندازه‌ها بر حسب پیکسل هستند. هر مقدار را می‌توان مستقل از بخش‌های دیگر تغییر داد.</p><table class="form-table" role="presentation"><?php bk_font_field($settings,'font_hero_title','عنوان هیرو');bk_font_field($settings,'font_benefit_title','عنوان مزیت‌ها');bk_font_field($settings,'font_benefit_text','توضیح مزیت‌ها');bk_font_field($settings,'font_categories_title','عنوان دسته‌بندی‌ها');bk_font_field($settings,'font_courses_title','عنوان بخش دوره‌ها');bk_font_field($settings,'font_course_title','عنوان کارت دوره');bk_font_field($settings,'font_about_title','عنوان بخش معرفی');bk_font_field($settings,'font_works_title','عنوان نمونه‌کارها');bk_font_field($settings,'font_testimonials_title','عنوان نظرات');bk_font_field($settings,'font_footer_title','عنوان‌های فوتر');bk_font_field($settings,'font_footer_text','متن‌های فوتر');bk_font_field($settings,'font_signature','امضای طراح');?></table><?php submit_button('ذخیره تنظیمات');?></form></div><script>jQuery(function($){$('.bk-select-media').on('click',function(e){e.preventDefault();const field=$(this).closest('.bk-media-field');const frame=wp.media({title:'انتخاب تصویر',button:{text:'استفاده از تصویر'},multiple:false,library:{type:'image'}});frame.on('select',function(){const a=frame.state().get('selection').first().toJSON();field.find('.bk-media-value').val(a.url);field.find('.bk-media-preview').html('<img src="'+a.url.replace(/"/g,'&quot;')+'" alt="" style="display:block;max-width:180px;max-height:100px;border-radius:10px;object-fit:contain;">');field.find('.bk-remove-media').show();});frame.open();});$('.bk-remove-media').on('click',function(){const field=$(this).closest('.bk-media-field');field.find('.bk-media-value').val('');field.find('.bk-media-preview').empty();$(this).hide();});});</script><?php }
